-- FoodCost: a starter list of common baking ingredients for the shared list (Admin → FoodCost), so a new user can cost a recipe at once
-- (docs/foodcost.md). Names in Bangla and English, how much a cup or a piece weighs, and nutrition per 100 g from USDA FoodData Central
-- (SR Legacy, public domain); NULL where the table gives no figure — the screens then say so, never guess. No prices: the owner sets the
-- Dhaka average in Admin, and each user can type their own. An ingredient whose name is already on the shared list is left as it is, so the
-- owner's own entries win and this file can never add a name twice.

INSERT INTO fc_ingredients (workspace_id, name_bn, name_en, category, g_per_ml, g_per_piece, kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, sort) SELECT NULL, 'ময়দা', 'All-purpose flour (maida)', 'আটা ও ময়দা · Flour', 0.53, NULL, 364, 10.3, 76.3, 1.0, 2.7, 0.3, 2, 100
  WHERE NOT EXISTS (SELECT 1 FROM fc_ingredients WHERE workspace_id IS NULL AND (lower(name_en) = lower('All-purpose flour (maida)') OR name_bn = 'ময়দা'));
